using System;using System.IO;using System.Linq;using Microsoft.CodeAnalysis;using Microsoft.CodeAnalysis.CSharp;using Sunward;
class Program{static void Require(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+name);}static void Main(){string root=Directory.Exists("Assets")?Directory.GetCurrentDirectory():Path.Combine(Directory.GetCurrentDirectory(),"unity");int count=0;foreach(var file in Directory.GetFiles(Path.Combine(root,"Assets"),"*.cs",SearchOption.AllDirectories)){var tree=CSharpSyntaxTree.ParseText(File.ReadAllText(file),path:file);var errors=tree.GetDiagnostics().Where(d=>d.Severity==DiagnosticSeverity.Error).ToArray();if(errors.Length>0)throw new Exception(string.Join("\n",errors.Select(e=>e.ToString())));if(Environment.GetEnvironmentVariable("SUNWARD_FORMAT")=="1")File.WriteAllText(file,tree.GetRoot().NormalizeWhitespace(indentation:"    ",eol:"\n").ToFullString()+"\n");count++;}Console.WriteLine("Parsed "+count+" C# files without syntax errors (not Unity API compilation).");var p=new ProfileData();Require(ProgressionRules.Validate(p),"fresh save validation");Require(!ProgressionRules.Buy(p,"strength"),"unaffordable purchase rejected");Require(ProgressionRules.Buy(p,"vitality")&&p.coins==5&&ProgressionRules.MaxHp(p)==112,"health purchase and cost");p.coins=500;Require(ProgressionRules.Buy(p,"unlock-sundial")&&p.equipped=="sundial"&&p.coins==390,"weapon unlock/equip");Require(!ProgressionRules.Buy(p,"unlock-sundial"),"duplicate weapon rejected");Require(ProgressionRules.Buy(p,"movement")&&ProgressionRules.Buy(p,"movement")&&p.upgrades.movement==2,"double-jump upgrade threshold");int coins=p.coins;p.defeats++;Require(p.coins==coins&&p.owned.Contains("sundial"),"defeat does not reset progression");p.xp=350;p.wins=2;Require(ProgressionRules.Level(p)==4&&ProgressionRules.Power(p)>10,"level/power growth");var store=new SaveStore();store.Data.coins=913;store.Data.windflowers=new[]{"garden"};store.Data.collectibles=new[]{"future-scroll"};store.Data.upgrades.movement=2;Require(store.Save(),"file save verified");store.Data.coins=700;Require(store.Save(),"backup save created");store.Data.coins=1;Require(store.Reload()&&store.Data.coins==700,"reload restores currency");Require(store.Data.windflowers.Contains("garden")&&store.Data.collectibles.Contains("future-scroll"),"quest/collectible save roundtrip");File.WriteAllText(store.Path,"broken JSON");Require(store.Reload()&&store.Data.coins==913,"corrupted current file recovers backup");Require(!store.Import("{broken")&&store.Data.coins==913,"invalid import keeps progress");store.Data.revision=100;Require(store.Save(),"high-revision checkpoint");Require(store.Import("{\"version\":2,\"coins\":222,\"xp\":35,\"owned\":[\"spear\",\"sundial\"],\"equipped\":\"sundial\",\"upgrades\":{\"strength\":2}}")&&store.Data.coins==222&&store.Data.equipped=="sundial", "browser-shaped save import");Require(store.Reload()&&store.Data.coins==222&&store.Data.revision>101,"import remains newer than Unity backup");Directory.Delete(UnityEngine.Application.persistentDataPath,true);p.upgrades.strength=99;Require(!ProgressionRules.Validate(p),"invalid upgrade cap rejected");}}
